// And groups predicates with the AND operator between them.
func And(predicates ...predicate.AIRoute) predicate.AIRoute {
	return predicate.AIRoute(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.AIRoute) predicate.AIRoute {
	return predicate.AIRoute(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.AIRoute) predicate.AIRoute {
	return predicate.AIRoute(sql.NotPredicates(p))
}
